('advanced-native-061', '["phrase"]'::jsonb, '{"advanced-native-061-v1-audio":{"type":"mc","answers":["領導能力需要時間和練習。"],"options":["領導能力需要時間和練習。","只要練一晚就一定能領導。","領導能力完全不能學習。","每個人學習領導的速度都相同。"]},"advanced-native-061-v2-reply":{"type":"mc","answers":["Regular practice will give you more chances to improve.","You cannot master it overnight.","Two lessons are only a beginning.","Your fingers need more time to learn the movements."],"options":["Regular practice will give you more chances to improve.","You cannot master it overnight.","Two lessons are only a beginning.","Your fingers need more time to learn the movements."]},"advanced-native-061-v1-scene":{"type":"mc","answers":["Fitness does not improve overnight."],"options":["One session guarantees lasting fitness.","Fitness cannot change through training.","Fitness does not improve overnight."]},"advanced-native-061-v1-contrast":{"type":"mc","answers":["Overnight 在任何句子中都保證剛好花了十二小時。"],"options":["It will not happen overnight 提醒事情需要時間。","Overnight 在任何句子中都保證剛好花了十二小時。","It changed overnight 可以指變化非常快。"]},"advanced-native-061-v1-branch":{"type":"mc","answers":["Speed does not improve overnight; try a little practice each day."],"options":["You should already be as fast as someone with years of practice.","Speed does not improve overnight; try a little practice each day.","If three days were not enough, practice can never help."]},"advanced-native-061-v1-final":{"type":"open","answers":["You will not become a skilled artist overnight. Keep practising a little each day.","Drawing well does not happen overnight, so give yourself time to learn."],"options":[]}}'::jsonb),
('advanced-native-062', '["phrase"]'::jsonb, '{"advanced-native-062-v1-audio":{"type":"mc","answers":["侍應面對問題時沒有慌亂，也有求助。"],"options":["侍應拒絕接受任何幫忙。","侍應面對問題時沒有慌亂，也有求助。","侍應根本沒有遇到任何壓力。","侍應不在乎訂單出錯。"]},"advanced-native-062-v2-reply":{"type":"mc","answers":["Try to stay calm under pressure and answer one question at a time.","Pause briefly before you answer.","Ask the audience to take turns.","Say when you need a moment to check a fact."],"options":["Try to stay calm under pressure and answer one question at a time.","Pause briefly before you answer.","Ask the audience to take turns.","Say when you need a moment to check a fact."]},"advanced-native-062-v1-scene":{"type":"mc","answers":["She stayed calm under pressure."],"options":["She had no demanding tasks to manage.","She ignored the waiting customers.","She stayed calm under pressure."]},"advanced-native-062-v1-contrast":{"type":"mc","answers":["一遇到緊張情況便慌亂大叫，無法聽取指示。"],"options":["繁忙時清楚分工並請求支援。","一遇到緊張情況便慌亂大叫，無法聽取指示。","臨時被追問時先整理思路再回答。"]},"advanced-native-062-v1-branch":{"type":"mc","answers":["You can feel nervous and still stay calm under pressure. Focus on the next step."],"options":["You can feel nervous and still stay calm under pressure. Focus on the next step.","Being calm means you must not care about the result.","If you ask for help, you have failed to stay calm."]},"advanced-native-062-v1-final":{"type":"open","answers":["We stayed calm under pressure and served one student at a time.","The queue was long, but we stayed calm under pressure by sharing the work."],"options":[]}}'::jsonb),
('advanced-native-063', '["phrase"]'::jsonb, '{"advanced-native-063-v1-audio":{"type":"mc","answers":["Mei 開始熟悉新工作並較有信心。"],"options":["Mei 決定離開新工作。","Mei 尚未開始上班。","Mei 開始熟悉新工作並較有信心。","Mei 已精通店內每項工作。"]},"advanced-native-063-v2-reply":{"type":"mc","answers":["I know my way around a little better now.","I have started talking to a few classmates.","The routine feels less confusing this week.","I am slowly finding my feet."],"options":["I know my way around a little better now.","I have started talking to a few classmates.","The routine feels less confusing this week.","I am slowly finding my feet."]},"advanced-native-063-v1-scene":{"type":"mc","answers":["She is finding her feet in the role."],"options":["She is finding her feet in the role.","She has decided the role is not for her and has left.","She has not yet experienced a day in the role."]},"advanced-native-063-v1-contrast":{"type":"mc","answers":["在同一職位多年，一切如常，沒有新的適應過程。"],"options":["新生漸漸熟習校園生活。","新職員開始掌握日常流程。","在同一職位多年，一切如常，沒有新的適應過程。"]},"advanced-native-063-v1-branch":{"type":"mc","answers":["It takes time to find your feet; ask me if the routine is unclear."],"options":["If you need time, you will never manage the job.","Finding your feet means you must know every answer already.","It takes time to find your feet; ask me if the routine is unclear."]},"advanced-native-063-v1-final":{"type":"open","answers":["I am finding my feet in the debate team and starting to share my ideas.","After a few meetings, I found my feet and felt more comfortable joining the discussion."],"options":[]}}'::jsonb),
('advanced-native-064', '["phrase"]'::jsonb, '{"advanced-native-064-v1-audio":{"type":"mc","answers":["他透過練習逐步處理緊張。"],"options":["他從來沒有感到緊張。","朋友替他完成了整場發言。","他決定完全不準備就退出。","他透過練習逐步處理緊張。"]},"advanced-native-064-v2-reply":{"type":"mc","answers":["She takes a short pause before each practice run.","She talks through her worries with her teacher.","She works through her nerves by rehearsing with a friend.","She practises the first minute until it feels familiar."],"options":["She takes a short pause before each practice run.","She talks through her worries with her teacher.","She works through her nerves by rehearsing with a friend.","She practises the first minute until it feels familiar."]},"advanced-native-064-v1-scene":{"type":"mc","answers":["She is working through her nerves."],"options":["She has never felt anxious about the stage.","She has cancelled every chance to perform.","She is working through her nerves."]},"advanced-native-064-v1-contrast":{"type":"mc","answers":["完全沒有緊張，直接完成早已熟練的任務，沒有處理情緒的過程。"],"options":["帶着一點緊張，分小步完成準備。","透過排練逐步處理焦慮。","完全沒有緊張，直接完成早已熟練的任務，沒有處理情緒的過程。"]},"advanced-native-064-v1-branch":{"type":"mc","answers":["Working through your nerves can mean continuing even while you feel nervous."],"options":["Working through your nerves can mean continuing even while you feel nervous.","You must stop until every nervous feeling has disappeared.","This phrase means you were never nervous at all."]},"advanced-native-064-v1-final":{"type":"open","answers":["She is working through her nerves by practising a short opening with her family.","She works through her nerves one line at a time, with help from her family."],"options":[]}}'::jsonb),
('advanced-native-066', '["phrase"]'::jsonb, '{"advanced-native-066-v1-audio":{"type":"mc","answers":["老師希望學生比較資料後自行判斷。"],"options":["老師已替學生作出每項決定。","老師希望學生比較資料後自行判斷。","老師要求學生照抄同一個答案。","老師禁止學生閱讀任何資料。"]},"advanced-native-066-v2-reply":{"type":"mc","answers":["Encourage them to think for themselves.","Ask them to compare the evidence.","Let them explain why they trust a source.","Show them how to question an unsupported claim."],"options":["Encourage them to think for themselves.","Ask them to compare the evidence.","Let them explain why they trust a source.","Show them how to question an unsupported claim."]},"advanced-native-066-v1-scene":{"type":"mc","answers":["They are thinking for themselves."],"options":["They are thinking for themselves.","They are repeating a conclusion without considering it.","They are refusing to consider any evidence."]},"advanced-native-066-v1-contrast":{"type":"mc","answers":["因為朋友都相信，便不加思考地照信。"],"options":["聆聽建議後自行決定合適做法。","比較證據後提出自己的理由。","因為朋友都相信，便不加思考地照信。"]},"advanced-native-066-v1-branch":{"type":"mc","answers":["You can think for yourself and still consider useful advice."],"options":["You can think for yourself and still consider useful advice.","Thinking for yourself means rejecting every fact someone gives you.","If you listen to advice, the final decision cannot be yours."]},"advanced-native-066-v1-final":{"type":"open","answers":["I need to think for myself and choose a topic that interests me.","I will compare the sources and think for myself before deciding on a research topic."],"options":[]}}'::jsonb),
('advanced-native-067', '["phrase"]'::jsonb, '{"advanced-native-067-v1-audio":{"type":"mc","answers":["承擔責任促進了他的領導成長。"],"options":["他把所有責任交回別人。","領導能力只與他的年資有關。","承擔責任促進了他的領導成長。","輪班安排令他不再需要學習。"]},"advanced-native-067-v2-reply":{"type":"mc","answers":["It gives us a reason to learn new skills.","We can learn to handle conflict.","It may reveal what we need to improve.","It can push people to grow."],"options":["It gives us a reason to learn new skills.","We can learn to handle conflict.","It may reveal what we need to improve.","It can push people to grow."]},"advanced-native-067-v1-scene":{"type":"mc","answers":["Life can push them to change homes without the account claiming that the move is beneficial."],"options":["Because they did not want to move, the circumstances cannot be said to have prompted their action.","The account says they chose the move to develop their careers before the lease ended unexpectedly.","Life can push them to change homes without the account claiming that the move is beneficial."]},"advanced-native-067-v1-contrast":{"type":"mc","answers":["只要任務變難，就能直接認定當事人已學會新的能力。"],"options":["新的責任可能使人更成熟。","只要任務變難，就能直接認定當事人已學會新的能力。","適度挑戰能促進能力發展。"]},"advanced-native-067-v1-branch":{"type":"mc","answers":["It could push you to grow, especially if you have guidance when you need it."],"options":["I assumed the invitation meant you had already learnt the parts you find unfamiliar.","I thought getting support would mean the role could no longer challenge you.","It could push you to grow, especially if you have guidance when you need it."]},"advanced-native-067-v1-final":{"type":"open","answers":["Your patient questions pushed me to grow as a writer: I learnt to listen before defending my first draft. Thank you for helping me investigate the readers’ doubts and revise the ending more thoughtfully.","This feedback pushed me to grow because I stopped treating every question as an attack and began asking readers what was unclear. I appreciate the time you gave me to work out a better ending."],"options":[]}}'::jsonb),
('advanced-native-068', '["phrase"]'::jsonb, '{"advanced-native-068-v1-audio":{"type":"mc","answers":["任務揭示了分數以外的實際能力。"],"options":["考試分數保證他們願意做所有工作。","任務只列出了他們的興趣。","任務證明他們已沒有需要學的事。","任務揭示了分數以外的實際能力。"]},"advanced-native-068-v2-reply":{"type":"mc","answers":["It gives them another way to demonstrate their abilities.","The results may reveal strengths we have missed.","It may show what they are really capable of.","Some useful skills are easier to see in action."],"options":["It gives them another way to demonstrate their abilities.","The results may reveal strengths we have missed.","It may show what they are really capable of.","Some useful skills are easier to see in action."]},"advanced-native-068-v1-scene":{"type":"mc","answers":["The task revealed what she was really capable of."],"options":["The task confirmed only which subject she preferred.","The task showed that she had already mastered every subject.","The task revealed what she was really capable of."]},"advanced-native-068-v1-contrast":{"type":"mc","answers":["它必定表示他們已願意接受每一項任務。"],"options":["它可作 showed 或 revealed 後面的內容。","它可以指以前未被發現的能力。","它必定表示他們已願意接受每一項任務。"]},"advanced-native-068-v1-branch":{"type":"mc","answers":["Being capable does not mean you have agreed."],"options":["Being capable means you have completed the task today.","Being capable does not mean you have agreed.","If you are capable of it, you have already agreed to do it."]},"advanced-native-068-v1-final":{"type":"open","answers":["The school sale showed what she was really capable of when she organised the stock.","We saw what she was really capable of as she brought order to the stockroom."],"options":[]}}'::jsonb),
('advanced-native-069', '["phrase"]'::jsonb, '{"advanced-native-069-v1-audio":{"type":"mc","answers":["學生逐步提升了面對挫折的恢復能力。"],"options":["學生逐步提升了面對挫折的恢復能力。","學生從此永遠不會難過。","學生不再需要任何支援。","挫敗本身保證每個人都立即變強。"]},"advanced-native-069-v2-reply":{"type":"mc","answers":["Remind them that they can ask for support.","Supportive feedback can help them build resilience.","Give them time to reflect on what happened.","Help them set one manageable next goal."],"options":["Remind them that they can ask for support.","Supportive feedback can help them build resilience.","Give them time to reflect on what happened.","Help them set one manageable next goal."]},"advanced-native-069-v1-scene":{"type":"mc","answers":["The process helped her build resilience."],"options":["The process helped her build resilience.","The tutor rewrote the piece for her.","The process taught her never to seek help."]},"advanced-native-069-v1-contrast":{"type":"mc","answers":["要求學生承受傷害，並禁止他們求助，因為這必定有益。"],"options":["培養遇到困難後調整做法的能力。","要求學生承受傷害，並禁止他們求助，因為這必定有益。","透過支援和反思逐步提升恢復能力。"]},"advanced-native-069-v1-branch":{"type":"mc","answers":["You can feel upset and still build resilience as you plan your next step."],"options":["Resilience means you must never feel disappointed.","You should refuse all support to prove you are strong.","You can feel upset and still build resilience as you plan your next step."]},"advanced-native-069-v1-final":{"type":"open","answers":["Rest and useful feedback helped the team build resilience after the defeat.","The players are building resilience by learning from the match and trying again with support."],"options":[]}}'::jsonb),
('advanced-native-070', '["phrase"]'::jsonb, '{"advanced-native-070-v1-audio":{"type":"mc","answers":["說話者當時的感受與後來的理解不同。"],"options":["說話者當時的感受與後來的理解不同。","說話者直到現在仍完全不明白。","說話者一開始已同意她離開。","說話者說她永遠不能離開。"]},"advanced-native-070-v2-reply":{"type":"mc","answers":["It felt stressful until someone explained the new plan.","In the moment, I felt quite lost.","At first, I did not know what to do.","I was surprised and needed a minute to think."],"options":["It felt stressful until someone explained the new plan.","In the moment, I felt quite lost.","At first, I did not know what to do.","I was surprised and needed a minute to think."]},"advanced-native-070-v1-scene":{"type":"mc","answers":["It felt serious in the moment."],"options":["I knew from the start that it did not matter.","It felt serious in the moment.","It has become more serious every year."]},"advanced-native-070-v1-contrast":{"type":"mc","answers":["它必定表示多年後的長期結果。"],"options":["它可與 later 作時間上的對比。","它可用來描述事件當時的感受。","它必定表示多年後的長期結果。"]},"advanced-native-070-v1-branch":{"type":"mc","answers":["It is hard to judge everything in the moment; what would help you pause next time?"],"options":["It is hard to judge everything in the moment; what would help you pause next time?","You must have known then everything you know now.","Do not reflect on the choice again; there is nothing useful to learn from it."]},"advanced-native-070-v1-final":{"type":"open","answers":["In the moment, I was disappointed, but later I understood the safety concern.","The cancellation felt unfair in the moment. Once I heard about the weather, I understood the decision."],"options":[]}}'::jsonb),
('advanced-native-071', '["phrase"]'::jsonb, '{"advanced-native-071-v1-audio":{"type":"mc","answers":["眼前花時間，後來可能帶來團隊好處。"],"options":["培訓完全不需要時間。","好處必須在今天內全部出現。","團隊已決定不再培訓任何人。","眼前花時間，後來可能帶來團隊好處。"]},"advanced-native-071-v2-reply":{"type":"mc","answers":["The team will be less dependent on one expert.","We may handle future work more confidently.","It could save us time in the long run.","Understanding it now may prevent repeated mistakes."],"options":["The team will be less dependent on one expert.","We may handle future work more confidently.","It could save us time in the long run.","Understanding it now may prevent repeated mistakes."]},"advanced-native-071-v1-scene":{"type":"mc","answers":["The practice may help her in the long run."],"options":["The practice may help her in the long run.","The practice must solve every problem today.","The practice has no possible later effect."]},"advanced-native-071-v1-contrast":{"type":"mc","answers":["只計算今天的購買價錢，不必考慮之後的成本。"],"options":["考慮眼前以外的後續影響。","只計算今天的購買價錢，不必考慮之後的成本。","可用來對比現在的成本與將來的好處。"]},"advanced-native-071-v1-branch":{"type":"mc","answers":["A reliable tool might cost less in the long run if it lasts longer."],"options":["Anything expensive is always cheaper in the long run.","Long-term costs only mean the price paid today.","A reliable tool might cost less in the long run if it lasts longer."]},"advanced-native-071-v1-final":{"type":"open","answers":["Organising files takes time now, but it could help us in the long run.","In the long run, a clear folder system may make homework easier to find."],"options":[]}}'::jsonb),
('advanced-native-072', '["phrase"]'::jsonb, '{"advanced-native-072-v1-audio":{"type":"mc","answers":["學生需要分析問題並嘗試辦法。"],"options":["任務只着重更快組裝新模型，而不是找出舊模型的故障。","學生不需要找出模型出了甚麼問題。","學生需要分析問題並嘗試辦法。","只要背指示就保證能完成。"]},"advanced-native-072-v2-reply":{"type":"mc","answers":["They can practise finding the cause of an error.","They can learn to test one change at a time.","They can become more careful about checking results.","They can develop problem-solving skills."],"options":["They can practise finding the cause of an error.","They can learn to test one change at a time.","They can become more careful about checking results.","They can develop problem-solving skills."]},"advanced-native-072-v1-scene":{"type":"mc","answers":["They are using their problem-solving skills."],"options":["They are avoiding the cause of the failure.","They are using their problem-solving skills.","They are only copying a finished answer without checking it."]},"advanced-native-072-v1-contrast":{"type":"mc","answers":["只照抄現成答案，不理解問題或作任何判斷。"],"options":["分析故障後逐一測試可能原因。","只照抄現成答案，不理解問題或作任何判斷。","比較不同方案，再依測試結果修正。"]},"advanced-native-072-v1-branch":{"type":"mc","answers":["Problem-solving skills also include testing a different approach when one fails."],"options":["If one attempt fails, analysing the cause is pointless.","Problem-solving skills also include testing a different approach when one fails.","Good problem-solving means the first idea must always work."]},"advanced-native-072-v1-final":{"type":"open","answers":["We used our problem-solving skills to improve the registration queue.","Comparing different queue layouts helped us develop problem-solving skills."],"options":[]}}'::jsonb),
('advanced-native-073', '["phrase"]'::jsonb, '{"advanced-native-073-v1-audio":{"type":"mc","answers":["競爭配合尊重和休息，做法較平衡。"],"options":["教練禁止所有挑戰。","競爭配合尊重和休息，做法較平衡。","競爭越傷害對手就越好。","隊員被要求完全不休息。"]},"advanced-native-073-v2-reply":{"type":"mc","answers":["Encourage students to compete in a healthy way.","Praise effort without humiliating anyone.","Make room for rest and friendly feedback.","Set challenging but realistic goals."],"options":["Encourage students to compete in a healthy way.","Praise effort without humiliating anyone.","Make room for rest and friendly feedback.","Set challenging but realistic goals."]},"advanced-native-073-v1-scene":{"type":"mc","answers":["They are competing in a healthy way."],"options":["They have removed every challenging goal.","They are competing in a healthy way.","They are competing by humiliating the other group."]},"advanced-native-073-v1-contrast":{"type":"mc","answers":["以持續羞辱和不准休息來逼迫表現。"],"options":["鼓勵改進，但避免羞辱和過度負擔。","以持續羞辱和不准休息來逼迫表現。","提出合理挑戰，同時讓學生求助。"]},"advanced-native-073-v1-branch":{"type":"mc","answers":["Challenge them in a healthy way by setting realistic steps and offering support."],"options":["A healthy challenge means everyone must find it effortless.","Challenge them in a healthy way by setting realistic steps and offering support.","If the goal is difficult, rest should be forbidden."]},"advanced-native-073-v1-final":{"type":"open","answers":["We can compete in a healthy way by respecting teammates and taking breaks.","Practise hard, but compete in a healthy way without mocking other players."],"options":[]}}'::jsonb),
